using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class PredictionController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly string[] _labels;

    public PredictionController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        IServiceProvider serviceProvider)
    {
        _predictionPool = predictionPool;

        // Retrieve label names from the trained model's schema
        var mlContext = new MLContext();
        var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        var model = mlContext.Model.Load(modelPath, out _);
        var schema = model.GetOutputSchema(SchemaDefinition.Create(typeof(TicketInput)));
        var labelColumn = schema["Label"];
        var keyType = labelColumn.Type as Microsoft.ML.Data.KeyDataViewType;
        VBuffer<ReadOnlyMemory<char>> keyValues = default;
        labelColumn.GetKeyValues(ref keyValues);
        _labels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
    }

    [HttpPost]
    public ActionResult<TicketPredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _labels.Length && i < prediction.Score.Length; i++)
        {
            confidence[_labels[i]] = prediction.Score[i];
        }

        return Ok(new TicketPredictionResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            Confidence = confidence
        });
    }
}

